import{_ as t,o as r,c as e,a2 as s}from"./chunks/framework.B2QVIpOM.js";const d=JSON.parse('{"title":"创知中学 · 2025年资料 · 中三 · 考试与面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-5efec1a0","school_zh":"创知中学","school_en":"—","grade":"s3","year":"2025-source","year_label":"2025年资料","type":"mixed","title":"创知中学 · 2025年资料 · 中三 · 考试与面试","anonymous":true,"source_ids":["SCIENTIA-S3-2025-OTHER","SCIENTIA-S3-20250509"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/school-5efec1a0/s3/2025-source-mixed.md","filePath":"reports/school-5efec1a0/s3/2025-source-mixed.md"}'),p={name:"reports/school-5efec1a0/s3/2025-source-mixed.md"};function n(a,o,c,g,l,i){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="创知中学-·-2025年资料-·-中三-·-考试与面试" tabindex="-1">创知中学 · 2025年资料 · 中三 · 考试与面试 <a class="header-anchor" href="#创知中学-·-2025年资料-·-中三-·-考试与面试" aria-label="Permalink to &quot;创知中学 · 2025年资料 · 中三 · 考试与面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-5efec1a0">← 返回创知中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-scientia-s3-2025-other" tabindex="-1">资料来源：创知中学插班中三考经_2025年秋季.pdf <a class="header-anchor" href="#record-scientia-s3-2025-other" aria-label="Permalink to &quot;资料来源：创知中学插班中三考经_2025年秋季.pdf {#record-scientia-s3-2025-other}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生／家长反馈整理</p><p><strong>入学途径：</strong> 插班</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 各科分别注明</p><p><strong>笔试与面试</strong></p><p>考试约两小时15分钟，中途安排普通话面试。该份记录没有具体日期，所列题目与5月9日的另一组反馈不同。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，口语未注明</p><p><strong>阅读及语言运用</strong></p><p>一篇现代文涉及香港旧街道，问“钢筋水泥”代表什么；一篇文言文讲后母对儿子不好，儿子仍善待后母并最终感化她。另有排比句、比喻句等语言运用。</p><p><strong>作文</strong></p><p>香港有许多中西结合的节日，选择喜欢的节日写作，要求300字以上。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>语言运用、阅读与写作</strong></p><p>不供词填空、语法（包括-ing／-ed形式）、阅读理解及约100字作文；作文题目未回忆。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>考点及具体表达式</strong></p><p>圆柱体表面积与体积、圆形公式、sin／cos／tan、因式分解、斜率、不等式、角度、坐标，以及二次函数图像和对称轴，回忆的表达式为y = 4 − (x − 3)²。</p></blockquote><blockquote><p><strong>学生面试：</strong> 普通话</p><p><strong>个人规划与校园适应</strong></p><p>自我介绍、未来选修科目或工作、平时如何通勤、为什么选择该校，以及有什么问题想问学校。</p></blockquote><h2 id="record-scientia-s3-20250509" tabindex="-1">资料来源：创知中学插班中三考经_2025年秋季.pdf <a class="header-anchor" href="#record-scientia-s3-20250509" aria-label="Permalink to &quot;资料来源：创知中学插班中三考经_2025年秋季.pdf {#record-scientia-s3-20250509}&quot;">​</a></h2><p><strong>资料类型：</strong> 多位学生反馈及机构整理</p><p><strong>入学途径：</strong> 插班</p><p><strong>课程分支：</strong> 课程分支未注明</p><p><strong>反馈时间：</strong> 2025年5月</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 各科分别注明</p><p><strong>合卷及穿插面试</strong></p><p>5月9日，中、英、数试卷一次发放，自主分配时间，笔试途中被叫去面试。不同反馈分别记为约135分钟或两个半小时。以下汇总多位学生同类流程下的题目，不代表每位考生经历完全相同。</p><p><strong>考场人数</strong></p><p>其中一份反馈记得中三三人、中四两人、中二三人及中一两人一同到场；属于该场观察，不是招生名额。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，口语未注明</p><p><strong>阅读与语言运用</strong></p><p>有常识、现代文、文言文，题型包括选择、修辞及判断。部分反馈记为两篇现代文；另一位记得一篇沙漠旅游故事：导游提醒夜间不可随处睡觉，所谓灵异事件最后被揭开。</p><p><strong>书信写作</strong></p><p>情境为上学途中在公交车睡着、坐过站，醒来到了陌生地方，又发现钱包遗失，费尽周折回校但迟到一小时。写信给教导主任解释经过，并承诺改进；一位考生记得要求150至200字。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>阅读与语法</strong></p><p>有选词填空、篇章填空、完形及语法填空。一位记得两篇阅读，另一位将两篇文章与两篇填词材料合计为四篇；文章分别涉及不同国家的节日庆祝方式及圣诞老人。后者记得没有改写句子、补全句子或改错题。</p><p><strong>四格图片写作</strong></p><p>女孩看到对面楼里发生冲突／劫案，报警后警察将涉事者带走。须交代看见什么、发生时间、自己第一时间如何处理及最后结果；一位还记得首图墙上写着“6”。</p></blockquote><blockquote><p><strong>数学：</strong> 中文</p><p><strong>题型与考点</strong></p><p>部分反馈记得选择与填空各约十题，简答约五至六题。涉及因式分解、代数、几何、函数、三角函数及容积。</p></blockquote><blockquote><p><strong>学生面试：</strong> 普通话或粤语，因人而异</p><p><strong>时间与形式</strong></p><p>个人面试，一份反馈约两至三分钟，另一份约五至十分钟、由一位考官面谈。</p><p><strong>家庭及来港安排</strong></p><p>会否粤语；父母是否工作；谁陪同来港；有无兄弟姐妹；自己及父母是否持香港身份、取得身份的途径和时间；是否在学校附近租住；考试后是否回内地、九月再来港。</p><p><strong>学习情况</strong></p><p>曾问英语学习是否困难。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>难度差异</strong></p><p>中文多被认为较简单，数学中等、几何稍难；英语评价不一，一位认为阅读及语法填空较简单，另一位认为文章可读懂但选项较复杂。</p></blockquote>',25)])])}const h=t(p,[["render",n]]);export{d as __pageData,h as default};
